insert into public.lessons (level_id, slug, title, description, category, duration_minutes, sort_order, is_published)
select levels.id, lesson.slug, lesson.title, lesson.description, lesson.category, lesson.duration_minutes,
  coalesce((select max(existing.sort_order) from public.lessons as existing where existing.level_id = levels.id), 0) + lesson.level_order,
  false
from (values
    ('pdf-150-c1-grammar', 'C1', 'Caderno avançado: gramática e sintaxe', 'Inversões, condicionais, ênfase, subjuntivo e estruturas complexas. Conteúdo em rascunho; revisar antes de publicar.', 'Gramática', 18, 1),
    ('pdf-150-c1-vocabulary', 'C1', 'Caderno avançado: vocabulário e collocations', 'Vocabulário preciso e combinações lexicais de nível avançado. Conteúdo em rascunho; revisar antes de publicar.', 'Vocabulário', 15, 2),
    ('pdf-150-c1-phrasal-prepositions', 'C1', 'Caderno avançado: phrasal verbs e preposições', 'Phrasal verbs, regência e preposições frequentes em inglês avançado. Conteúdo em rascunho; revisar antes de publicar.', 'Vocabulário', 15, 3),
    ('pdf-150-c2-expressions', 'C2', 'Caderno avançado: expressões e colocações', 'Expressões fixas, colocações e nuances de uso. Conteúdo em rascunho; revisar antes de publicar.', 'Vocabulário', 15, 1),
    ('pdf-150-c2-grammar-accuracy', 'C2', 'Caderno avançado: precisão gramatical', 'Identificação de estruturas gramaticais corretas e precisão formal. Conteúdo em rascunho; revisar antes de publicar.', 'Gramática', 15, 2),
    ('pdf-150-c2-sentence-completion', 'C2', 'Caderno avançado: completar frases', 'Complete estruturas avançadas sem alternativas. As variantes do gabarito foram preservadas quando indicadas. Conteúdo em rascunho; revisar antes de publicar.', 'Escrita', 18, 3)
) as lesson(slug, level_code, title, description, category, duration_minutes, level_order)
join public.languages on languages.code = 'en'
join public.language_levels as levels on levels.language_id = languages.id and levels.code = lesson.level_code
on conflict (slug) do nothing;

