    (1, 'pdf-150-c1-grammar', 'hard', 'multiple_choice', 'No sooner _____ the announcement than the audience began to protest.', '["the chair had made","had the chair made","did the chair make","the chair made"]'::jsonb, 2::integer, null::text[], 'Importado do caderno avançado, questão 1. Revisar antes de publicar.'),
