), prepared_questions as (
  select question_data.*, row_number() over (partition by question_data.lesson_slug order by question_data.source_number)::smallint as question_order
  from question_data
), inserted_questions as (
  insert into public.questions (lesson_id, question_type, prompt, choices, sort_order, is_published, difficulty)
  select lessons.id, prepared.question_type, prepared.prompt, prepared.choices, prepared.question_order, false, prepared.difficulty
  from prepared_questions as prepared
  join public.lessons on lessons.slug = prepared.lesson_slug
  on conflict (lesson_id, sort_order) do nothing
  returning id, lesson_id, sort_order
)
insert into public.question_answers (question_id, accepted_answers, explanation)
select inserted.id,
  case when prepared.correct_choice is not null then array[prepared.choices ->> (prepared.correct_choice - 1)] else prepared.written_answers end,
  prepared.explanation
from inserted_questions as inserted
join public.lessons on lessons.id = inserted.lesson_id
join prepared_questions as prepared on prepared.lesson_slug = lessons.slug and prepared.question_order = inserted.sort_order;
